import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"38、【睽】 兑下离上","description":"温公易说 - 38、【睽】 兑下离上","frontmatter":{"title":"38、【睽】 兑下离上","description":"温公易说 - 38、【睽】 兑下离上"},"headers":[],"relativePath":"zh/classics/wengong/039.md","filePath":"zh/classics/wengong/039.md"}'),n={name:"zh/classics/wengong/039.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_38、【睽】-兑下离上" tabindex="-1">38、【睽】 兑下离上 <a class="header-anchor" href="#_38、【睽】-兑下离上" aria-label="Permalink to “38、【睽】 兑下离上”">​</a></h1><p>注意</p><p>案原本缺。</p><h3 id="彖曰-睽-火动而上-泽动而下。二女同居-其志不同。行说而丽乎明-柔进而上行-得中而应乎刚-是以小事吉。天地睽而其事同也-男女睽而其志通也-万物睽而其事类也。睽之时用大矣哉。" tabindex="-1">彖曰：睽，火动而上，泽动而下。二女同居，其志不同。行说而丽乎明，柔进而上行，得中而应乎刚，是以小事吉。天地睽而其事同也，男女睽而其志通也，万物睽而其事类也。睽之时用大矣哉。 <a class="header-anchor" href="#彖曰-睽-火动而上-泽动而下。二女同居-其志不同。行说而丽乎明-柔进而上行-得中而应乎刚-是以小事吉。天地睽而其事同也-男女睽而其志通也-万物睽而其事类也。睽之时用大矣哉。" aria-label="Permalink to “彖曰：睽，火动而上，泽动而下。二女同居，其志不同。行说而丽乎明，柔进而上行，得中而应乎刚，是以小事吉。天地睽而其事同也，男女睽而其志通也，万物睽而其事类也。睽之时用大矣哉。”">​</a></h3><h3 id="象曰-上火下泽-睽。君子以同而异。" tabindex="-1">象曰：上火下泽，睽。君子以同而异。 <a class="header-anchor" href="#象曰-上火下泽-睽。君子以同而异。" aria-label="Permalink to “象曰：上火下泽，睽。君子以同而异。”">​</a></h3><h3 id="初九-悔亡-丧马勿逐-自复-见恶人-无咎-象曰-见恶人-以辟咎也。" tabindex="-1">初九：悔亡，丧马勿逐，自复；见恶人，无咎 象曰：见恶人，以辟咎也。 <a class="header-anchor" href="#初九-悔亡-丧马勿逐-自复-见恶人-无咎-象曰-见恶人-以辟咎也。" aria-label="Permalink to “初九：悔亡，丧马勿逐，自复；见恶人，无咎 象曰：见恶人，以辟咎也。”">​</a></h3><h3 id="九二-遇主于巷-无咎-象曰-遇主于巷-未失道也。" tabindex="-1">九二：遇主于巷，无咎 象曰：遇主于巷，未失道也。 <a class="header-anchor" href="#九二-遇主于巷-无咎-象曰-遇主于巷-未失道也。" aria-label="Permalink to “九二：遇主于巷，无咎 象曰：遇主于巷，未失道也。”">​</a></h3><h3 id="六三-见舆曵-其牛掣-其人天且劓-无初有终-象曰-见舆曵-位不当也-无初有终-遇刚也。" tabindex="-1">六三：见舆曵，其牛掣，其人天且劓，无初有终 象曰：见舆曵，位不当也；无初有终，遇刚也。 <a class="header-anchor" href="#六三-见舆曵-其牛掣-其人天且劓-无初有终-象曰-见舆曵-位不当也-无初有终-遇刚也。" aria-label="Permalink to “六三：见舆曵，其牛掣，其人天且劓，无初有终 象曰：见舆曵，位不当也；无初有终，遇刚也。”">​</a></h3><h3 id="九四-睽孤-遇元夫-交孚-厉无咎-象曰-交孚无咎-志行也。" tabindex="-1">九四：睽孤，遇元夫，交孚，厉无咎 象曰：交孚无咎，志行也。 <a class="header-anchor" href="#九四-睽孤-遇元夫-交孚-厉无咎-象曰-交孚无咎-志行也。" aria-label="Permalink to “九四：睽孤，遇元夫，交孚，厉无咎 象曰：交孚无咎，志行也。”">​</a></h3><h3 id="六五-悔亡-厥宗噬肤-往何咎-象曰-厥宗噬肤-往有庆也。" tabindex="-1">六五：悔亡，厥宗噬肤，往何咎 象曰：厥宗噬肤，往有庆也。 <a class="header-anchor" href="#六五-悔亡-厥宗噬肤-往何咎-象曰-厥宗噬肤-往有庆也。" aria-label="Permalink to “六五：悔亡，厥宗噬肤，往何咎 象曰：厥宗噬肤，往有庆也。”">​</a></h3><h3 id="上九-睽孤-见豕负涂-载鬼一车-先张之弧-后说之弧-匪寇婚媾。往遇雨则吉-象曰-遇雨之吉-群疑亡也。" tabindex="-1">上九：睽孤，见豕负涂，载鬼一车，先张之弧，后说之弧，匪寇婚媾。往遇雨则吉 象曰：遇雨之吉，群疑亡也。 <a class="header-anchor" href="#上九-睽孤-见豕负涂-载鬼一车-先张之弧-后说之弧-匪寇婚媾。往遇雨则吉-象曰-遇雨之吉-群疑亡也。" aria-label="Permalink to “上九：睽孤，见豕负涂，载鬼一车，先张之弧，后说之弧，匪寇婚媾。往遇雨则吉 象曰：遇雨之吉，群疑亡也。”">​</a></h3>',11)])])}const m=e(n,[["render",l]]);export{b as __pageData,m as default};
